<?php
declare(strict_types=1);
require __DIR__ . '/bootstrap.php';
require_once __DIR__ . '/oxb.php';
require_once __DIR__ . '/wallet.php';
require_once __DIR__ . '/interserver.php';
$user = require_login();

$providerRows = [];
try {
    $stmt = db()->prepare('SELECT provider FROM user_identities WHERE user_id = ?');
    $stmt->execute([(int)$user['id']]);
    $providerRows = $stmt->fetchAll(PDO::FETCH_COLUMN);
} catch (Throwable $t) { error_log('oxbothost identity lookup failed: ' . $t->getMessage()); }
$user['full_name'] = (string)($user['name'] ?? '');
$user['phone_code'] = (string)($user['dial_code'] ?? '');
$user['google_id'] = in_array('google', $providerRows, true) ? 'linked' : null;
$user['github_id'] = in_array('github', $providerRows, true) ? 'linked' : null;
$user['password_hash'] = $user['password_hash'] ?? 'configured';
$user['last_login_at'] = $user['last_login_at'] ?? null;

if ($_SERVER['REQUEST_METHOD'] === 'POST' && ($_POST['action'] ?? '') === 'logout') {
    if (verify_csrf($_POST['csrf'] ?? null)) { logout_user(); redirect_to('login.php'); }
    http_response_code(400); exit('Invalid request.');
}
$e = fn($v) => htmlspecialchars((string)$v, ENT_QUOTES, 'UTF-8');
$first = explode(' ', trim($user['full_name']))[0];
$initial = strtoupper(mb_substr($user['full_name'], 0, 1));
$hour=(int)date('G'); $greeting=$hour<12?'Good morning':($hour<18?'Good afternoon':'Good evening');
$fmt=fn($d)=>$d?date('j M Y',strtotime($d)):'—';
$methods=array_filter([($user['password_hash']??'')?'Email & password':null,$user['google_id']?'Google':null,$user['github_id']?'GitHub':null]);
$counts=['domains'=>0,'hosting'=>0,'vps'=>0,'servers'=>0]; $recent=[];
try{$counts=oxb_counts((int)$user['id']);$recent=oxb_recent_orders((int)$user['id'],3);}catch(Throwable $t){error_log('oxbothost dashboard data failed: '.$t->getMessage());}
$walletBalance=0.0;$walletHistory=[];$products=[];
try{$walletBalance=wallet_balance((int)$user['id']);$walletHistory=wallet_history((int)$user['id'],10);}catch(Throwable $t){error_log('oxbothost wallet data failed: '.$t->getMessage());}
try{$api=new InterServerAPI(cfg('interserver.api_key'));$products=oxb_interserver_products($api,(float)cfg('interserver.markup',1.00));}catch(Throwable $t){error_log('InterServer catalog failed: '.$t->getMessage());}
$productsByCategory=[];foreach($products as $p)$productsByCategory[$p['category']][]=$p;
$categoryLabels=['hosting'=>'Web hosting','vps'=>'VPS','backup'=>'Backup & storage','mail'=>'Business mail','license'=>'Licenses'];
$flash=null;if(isset($_GET['deposited']))$flash='Deposit added to your wallet.';elseif(isset($_GET['bought']))$flash=(string)$_GET['bought'].' purchased.';elseif(isset($_GET['wallet_error']))$flash=(string)$_GET['wallet_error'];
$pages=['domains'=>'domain.php','hosting'=>'hosting.php','vps'=>'vps.php','servers'=>'server.php','orders'=>'orders.php','support'=>'support.php'];
function ico(string $n):string{$p=['home'=>'<path d="M3 11l9-8 9 8"/><path d="M5 10v10h14V10"/>','domains'=>'<circle cx="12" cy="12" r="9"/><path d="M3 12h18"/><path d="M12 3c3 3 3 15 0 18M12 3c-3 3-3 15 0 18"/>','hosting'=>'<rect x="3" y="4" width="18" height="7" rx="2"/><rect x="3" y="13" width="18" height="7" rx="2"/><path d="M7 7.5h.01M7 16.5h.01"/>','vps'=>'<rect x="5" y="5" width="14" height="14" rx="2"/><rect x="9" y="9" width="6" height="6"/><path d="M9 2v3M15 2v3M9 19v3M15 19v3M2 9h3M2 15h3M19 9h3M19 15h3"/>','servers'=>'<rect x="2" y="3" width="20" height="8" rx="2"/><rect x="2" y="13" width="20" height="8" rx="2"/><path d="M6 7h.01M6 17h.01M10 7h8M10 17h8"/>','support'=>'<circle cx="12" cy="12" r="9"/><circle cx="12" cy="12" r="3.5"/><path d="M5.6 5.6l3.9 3.9M14.5 14.5l3.9 3.9M18.4 5.6l-3.9 3.9M9.5 14.5l-3.9 3.9"/>','account'=>'<circle cx="12" cy="8" r="4"/><path d="M4 21c1-4 4-6 8-6s7 2 8 6"/>','menu'=>'<path d="M4 7h16M4 12h16M4 17h16"/>','close'=>'<path d="M6 6l12 12M18 6L6 18"/>','check'=>'<path d="M5 12l5 5 9-10"/>','arrow'=>'<path d="M5 12h14M13 6l6 6-6 6"/>','orders'=>'<path d="M6 3h12v18l-3-2-3 2-3-2-3 2z"/><path d="M9 8h6M9 12h6"/>','wallet'=>'<rect x="3" y="6" width="18" height="13" rx="2"/><path d="M3 10h18"/><circle cx="16.5" cy="14" r="1.2"/>'];return '<svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">'.($p[$n]??'').'</svg>';}
$nav=['home'=>['Home','#home'],'wallet'=>['Wallet','#wallet'],'domains'=>['Domains',$pages['domains']],'hosting'=>['Hosting',$pages['hosting']],'vps'=>['VPS',$pages['vps']],'servers'=>['Servers',$pages['servers']],'orders'=>['Orders',$pages['orders']],'support'=>['Support',$pages['support']],'account'=>['Account','#account']];
?>
