s"><?php foreach($walletHistory as $tx):?><li><div class="txt"><b><?=$e($tx['description']?:ucfirst((string)$tx['type']))?></b><small><?=$e(date('j M Y',strtotime((string)$tx['created_at'])))?></small></div><span class="badge<?=((float)$tx['amount']>=0?' solid':'')?>"><?=((float)$tx['amount']>=0?'+':'').$e(number_format((float)$tx['amount'],2))?></span></li><?php endforeach;?></ul><?php endif;?></div></div><?php foreach($categoryLabels as $cat=>$label):?><?php if(empty($productsByCategory[$cat]))continue;?><div class="card" style="margin-top:16px"><h2><?=$e($label)?></h2><div class="tiles" style="grid-template-columns:repeat(3,1fr)"><?php foreach($productsByCategory[$cat] as $p):?><form method="post" action="wallet_buy.php" class="tile" style="cursor:default"><input type="hidden" name="csrf" value="<?=$e(csrf_token())?>"><input type="hidden" name="product_id" value="<?=$e($p['id'])?>"><span class="t-l"><?=$e($p['name'])?></span><span class="t-n" style="font-size:1.9rem;margin-top:14px">$<?=$e(number_format($p['cost'],2))?></span><span class="t-s">per <?=$e($p['period'])?> · includes $1 Oxbothost markup</span><button class="btn sm" type="submit" style="margin-top:14px;width:100%">Buy</button></form><?php endforeach;?></div></div><?php endforeach;?><?php if(!$products):?><div class="card" style="margin-top:16px"><p class="sub">Products aren't loading from InterServer right now — check the server-side InterServer username/API key configuration.</p></div><?php endif;?></section><section class="view" id="view-account" data-title="Account"><div class="head"><h1>Account</h1><p class="sub">Your details and how you sign in.</p></div><div class="card" style="margin-top:26px;max-width:640px"><div class="acct"><span class="avatar"><?php if($user['avatar_url']):?><img src="<?=$e($user['avatar_url'])?>" alt="" referrerpolicy="no-referrer"><?php else:?><?=$e($initial)?><?php endif;?></span><div><b><?=$e($user['full_name'])?></b><small><?=$e($user['email'])?></small></div></div><dl class="kv"><dt>Email</dt><dd><?=$e($user['email'])?> <span class="badge <?=$user['email_verified']?'solid':'warn'?>"><?=$user['email_verified']?'Verified':'Unverified'?></span></dd><dt>Country</dt><dd><?=$e($user['country']?:'—')?></dd><dt>Phone</dt><dd><?=$user['phone']?$e($user['phone_code'].' '.$user['phone']):'—'?></dd><dt>Sign-in methods</dt><dd><?=$e(implode(', ',$methods))?></dd><dt>Member since</dt><dd><?=$e($fmt($user['created_at']))?></dd><dt>Last login</dt><dd><?=$e($fmt($user['last_login_at']))?></dd></dl></div></section></main></div></div><div class="toast" id="toast" role="status" aria-live="polite"></div><script>(function(){var views=[].slice.call(document.querySelectorAll('.view')),links=[].slice.call(document.querySelectorAll('[data-v]')),crumb=document.getElementById('crumb'),nav=document.getElementById('nav-toggle'),menu=document.getElementById('usermenu');function show(v){if(!document.getElementById('view-'+v))v='home';views.forEach(function(s){s.classList.toggle('on',s.id==='view-'+v)});links.forEach(function(a){if(a.classList.contains('rl'))a.classList.toggle('on',a.dataset.v===v)});crumb.textContent=document.getElementById('view-'+v).dataset.title;nav.checked=false;menu.open=false;window.scrollTo(0,0)}links.forEach(function(a){a.addEventListener('click',function(ev){ev.preventDefault();history.replaceState(null,'','#'+a.dataset.v);show(a.dataset.v)})});show(location.hash.slice(1)||'home')})();</script></body></html>
